fn prepare_layout(state: &mut AppState, size: PhysicalSize<u32>, scale: f32) {
    state.layout.compute(
        state.root,
        (
            Some(size.width as f32 / scale),
            Some(size.height as f32 / scale),
        ),
        |_, _, _, _, _| Size::ZERO,
    );
}

fn render_all(state: &mut AppState, viewport_rect: [f32; 4]) {
    let bg = hex_to_f4(THEME_BG);
    state.core.draw_list.push_quad(akar_core::QuadCall {
        rect: [0.0, 0.0, viewport_rect[2], viewport_rect[3]],
        fill: bg,
        border_color: [0.0; 4],
        corner_radii: [0.0; 4],
        border_width: 0.0,
        z: 0.0,
        shadow_blur: 0.0,
        shadow_spread: 0.0,
        shadow_color: [0.0; 4],
        shadow_offset: [0.0; 2],
        _pad: [0.0; 2],
    });

    let header_rect = state.layout.rect(state.header_node);
    render_mimo_header(state, header_rect);

    let scroll_rect = state.layout.rect(state.scroll_container);
    let paper_rect = state.layout.rect(state.paper_section);
    let content_height = (paper_rect[1] + paper_rect[3]) - scroll_rect[1];
    let resp = scroll_area_begin(
        &mut state.core,
        scroll_rect,
        &mut state.scroll_y,
        content_height,
    );
    let offset_y = resp.content_y - scroll_rect[1];

    state.core.draw_list.push_quad(akar_core::QuadCall {
        rect: [
            scroll_rect[0],
            scroll_rect[1],
            scroll_rect[2],
            content_height,
        ],
        fill: bg,
        border_color: [0.0; 4],
        corner_radii: [0.0; 4],
        border_width: 0.0,
        z: 0.0,
        shadow_blur: 0.0,
        shadow_spread: 0.0,
        shadow_color: [0.0; 4],
        shadow_offset: [0.0; 2],
        _pad: [0.0; 2],
    });

    let hero_abs = state.layout.rect(state.hero_node);
    let build_abs = state.layout.rect(state.build_section);
    let gap_bg_top = hero_abs[1] + hero_abs[3];
    let gap_bg_height = build_abs[1] - gap_bg_top;
    if gap_bg_height > 0.0 {
        state.core.draw_list.push_quad(akar_core::QuadCall {
            rect: [
                scroll_rect[0],
                gap_bg_top + offset_y,
                scroll_rect[2],
                gap_bg_height,
            ],
            fill: bg,
            border_color: [0.0; 4],
            corner_radii: [0.0; 4],
            border_width: 0.0,
            z: 0.0,
            shadow_blur: 0.0,
            shadow_spread: 0.0,
            shadow_color: [0.0; 4],
            shadow_offset: [0.0; 2],
            _pad: [0.0; 2],
        });
    }

    let hero_rect = state.layout.rect(state.hero_node);
    let hero_rect = [
        hero_rect[0],
        hero_rect[1] + offset_y,
        hero_rect[2],
        hero_rect[3],
    ];
    render_mimo_hero(state, hero_rect);

    let card_rects: Vec<[f32; 4]> = state
        .card_nodes
        .iter()
        .map(|&n| state.layout.rect(n))
        .collect();

    let cards_with_y: Vec<[f32; 4]> = card_rects
        .iter()
        .map(|&r| [r[0], r[1] + offset_y, r[2], r[3]])
        .collect();
    let cards_left = cards_with_y
        .iter()
        .map(|r| r[0])
        .fold(f32::INFINITY, f32::min);
    let cards_top = cards_with_y
        .iter()
        .map(|r| r[1])
        .fold(f32::INFINITY, f32::min);
    let cards_right = cards_with_y
        .iter()
        .map(|r| r[0] + r[2])
        .fold(f32::NEG_INFINITY, f32::max);
    let cards_bottom = cards_with_y
        .iter()
        .map(|r| r[1] + r[3])
        .fold(f32::NEG_INFINITY, f32::max);
    state.core.draw_list.push_quad(akar_core::QuadCall {
        rect: [
            cards_left,
            cards_top,
            cards_right - cards_left,
            cards_bottom - cards_top,
        ],
        fill: bg,
        border_color: [0.0; 4],
        corner_radii: [0.0; 4],
        border_width: 0.0,
        z: 0.0,
        shadow_blur: 0.0,
        shadow_spread: 0.0,
        shadow_color: [0.0; 4],
        shadow_offset: [0.0; 2],
        _pad: [0.0; 2],
    });
    for (i, card_rect) in card_rects.into_iter().enumerate() {
        let card_rect = [
            card_rect[0],
            card_rect[1] + offset_y,
            card_rect[2],
            card_rect[3],
        ];
        render_mimo_card(&mut state.core, card_rect, i);
    }

    let build_rect = state.layout.rect(state.build_section);
    let build_rect = [
        build_rect[0],
        build_rect[1] + offset_y,
        build_rect[2],
        build_rect[3],
    ];
    render_mimo_build_section(&mut state.core, build_rect);

    let paper_rect = [
        paper_rect[0],
        paper_rect[1] + offset_y,
        paper_rect[2],
        paper_rect[3],
    ];
    render_mimo_paper_section(&mut state.core, paper_rect);

    scroll_area_end(&mut state.core);
}

