            let x_offset = if row % 2 == 0 { 0.0 } else { -40.0 };
            let buf = core.text_pipeline.set_text(
                Some(3000 + row),
                pattern_text,
                glyphon::Metrics::new(28.0, 28.0 * 1.2),
                Some(hero_rect[2] + 80.0),
                None,
                None,
            );
            core.draw_list.push_text(akar_core::TextCall {
                buffer_id: buf,
                x: hero_rect[0] + x_offset,
                y,
                clip: hero_rect,
                color: pattern_color,
                z: 0.0,
            });
            y += row_height;
            row += 1;
